import Foundation
@testable import SoundModel
import SessionStore

// "Nothing else moved." This file uses only model API that existed before the three
// sounds, so the same code produced Fixtures/baseline.json from the tree before the
// change. The expectations are frozen there and never regenerated by the test.

enum QMSBaseline {
    static let root = RootUseID(UUID(uuidString: "00000000-0000-0000-0000-0000000000A1")!)
    static let soundModelFixtures = ["controls-v4.session.json", "everyday-01.session.json",
                                     "everyday-v5-library.json", "filters-v5-library.json"]
    static let candidateFixture = "Tests/QuickMenuSoundsChecks/Fixtures/quick-menu-candidate-library.json"

    static func line(_ parts: [ListeningRenderPart]) -> String {
        parts.map { part in
            part.id.uuidString + ":" + part.path.map(\.uuidString).joined(separator: "/") + ":" + part.type + ":"
                + part.parameters.map { $0.key + "=" + String($0.value) }.joined(separator: ",")
        }.joined(separator: "|")
    }

    static func isNewBuiltin(_ name: String, origin: String) -> Bool { origin == "builtin" && QMS.newNames.contains(name) }

    /// Each existing built-in's canonical payload, hash and native values over a sweep of its controls.
    static func builtins() throws -> [String: String] {
        let profiles = try LibraryProfiles()
        let context = LibraryCompileContext(profiles: profiles, revisions: [:], limits: QMS.limits.expansion)
        var out: [String: String] = [:]
        for (setName, set) in [("standard", LibraryBuiltinSet.standard), ("quickMenu", .quickMenu)] {
            let archive = try LibraryArchive.initial(profiles: profiles, builtins: set)
            for revision in archive.revisions where !isNewBuiltin(revision.definition.name, origin: revision.origin) {
                let key = setName + " " + revision.definition.name
                let payload = revision.payload
                out[key + " revision"] = [payload.profile, revision.definition.id.rawValue.uuidString,
                    revision.definition.version.rawValue.uuidString, revision.contentHash,
                    libraryDigest(try payload.canonicalData), "v\(payload.canonicalVersion)"].joined(separator: " ")
                let block = payload.block
                func at(_ control: SoundControl) -> OccurrenceControlKey { OccurrenceControlKey(path: [], control: control.id) }
                func grid(_ control: SoundControl) throws -> [Position] {
                    if case .choice(let choice) = control.face { return choice.positions }
                    return try [0, 0.25, 0.5, 0.75, 1].map { try Position($0) }
                }
                var frames: [[OccurrenceControlKey: ControlValue]] = [[:]]
                for control in block.controls {
                    for p in try grid(control) { frames.append([at(control): .scalar(p)]) }
                }
                let choices = block.controls.filter { if case .choice = $0.face { return true }; return false }
                if choices.count >= 2 {
                    for p in try grid(choices[0]) { for q in try grid(choices[1]) {
                        frames.append([at(choices[0]): .scalar(p), at(choices[1]): .scalar(q)])
                    } }
                }
                for relation in block.optionControls {
                    guard let parent = block.controls.first(where: { $0.id == relation.parentChoice }),
                          case .choice(let choice) = parent.face,
                          let child = block.controls.first(where: { $0.id == relation.child }) else { continue }
                    let option = try choice.position(of: relation.option)
                    for p in try grid(child) { frames.append([at(parent): .scalar(option), at(child): .scalar(p)]) }
                }
                var text = ""
                for frame in frames {
                    let sound = try CompiledSound(payload: payload, root: root, reference: nil, context: context,
                                                  listening: UseListeningState(values: frame))
                    text += line(try profiles.native(sound)) + "\n"
                }
                out[key + " native"] = libraryDigest(Data(text.utf8)) + " frames=\(frames.count)"
            }
        }
        return out
    }

    /// A loaded library, minus the per-load random use and assignment IDs.
    static func describe(_ snapshot: LibrarySnapshot) -> String {
        let definitions = snapshot.definitions.filter { !isNewBuiltin($0.name, origin: $0.origin) }.map {
            [$0.id.uuidString, $0.revision.uuidString, $0.name, $0.origin, $0.profile, $0.contentHash, "\($0.inTheMenu)"].joined(separator: " ")
        }
        let uses = snapshot.uses.sorted { $0.target < $1.target }.map { use in
            [use.target, use.definition.uuidString, use.baseRevision.uuidString, use.name, "\(use.hasOwnName)"].joined(separator: " ") + " "
                + use.positions.sorted { $0.key.uuidString < $1.key.uuidString }.map { "\($0.key.uuidString)=\($0.value)" }.joined(separator: ",")
        }
        let assignments = snapshot.assignments.sorted { $0.target < $1.target }.map {
            [$0.target, "\($0.isEnabled)", $0.definition.uuidString, line($0.parts)].joined(separator: " ")
        }
        return (["enabled \(snapshot.isEnabled)"] + definitions + uses + assignments).joined(separator: "\n")
    }

    /// The saved-sound fixtures as the app imports them, and a saved Quick Menu candidate library.
    static func savedSounds(root: URL, scratch: URL) async throws -> [String: String] {
        var out: [String: String] = [:]
        let folder = scratch.appendingPathComponent("baseline-fixtures")
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        for name in soundModelFixtures {
            let data = try Data(contentsOf: root.appendingPathComponent("Tests/SoundModelTests/Fixtures/" + name))
            let source: LibraryMigrationSource = name.hasSuffix("session.json") ? .v1(data) : .schema2(data)
            let destination = folder.appendingPathComponent(name)
            try? FileManager.default.removeItem(at: destination)
            let result = await SoundLibrarySession.open(persistence: LibrarySessionFile(url: destination, maximumBytes: QMS.limits.maximumBytes),
                                                        limits: QMS.limits, migrationSource: source)
            switch result {
            case .migrated(let session, _): out["fixture " + name] = libraryDigest(Data(describe(try await session.snapshot()).utf8))
            case .fresh: out["fixture " + name] = "opened fresh"
            case .existing: out["fixture " + name] = "opened existing"
            case .refused: out["fixture " + name] = "refused"
            case .unresolved: out["fixture " + name] = "unresolved"
            }
        }
        let candidate = root.appendingPathComponent(candidateFixture)
        if FileManager.default.fileExists(atPath: candidate.path) {
            let copy = folder.appendingPathComponent("candidate.json")
            try? FileManager.default.removeItem(at: copy)
            try FileManager.default.copyItem(at: candidate, to: copy)
            let before = try Data(contentsOf: copy)
            let session = try await QMSSession.reopen(copy)
            out["candidate library"] = libraryDigest(Data(describe(try await session.session.snapshot()).utf8))
            out["candidate library untouched by opening"] = "\(try Data(contentsOf: copy) == before)"
        }
        return out
    }

    /// Writes the candidate fixture: a Quick Menu library saved with Everyday and Filters in use.
    static func makeCandidate(_ file: URL) async throws {
        let s = try await QMSSession.fresh(file)
        try await s.select("Everyday", on: "candidate.one")
        try await s.choose("Place", "Corner", on: "candidate.one")
        try await s.moveChild("Place", "Corner", on: "candidate.one", to: 0.3)
        try await s.moveRow("Volume", on: "candidate.one", to: 0.6)
        try await s.moveRow("Softer", on: "candidate.one", to: 0.25)
        try await s.select("Filters", on: "candidate.two")
        try await s.moveRow("Low cut", on: "candidate.two", to: 0.4)
        _ = try await s.session.checkpoint()
    }

    static func all(root: URL, scratch: URL) async throws -> [String: String] {
        try builtins().merging(try await savedSounds(root: root, scratch: scratch)) { a, _ in a }
    }

    // 8. Nothing else moved.
    static func group(_ c: QMSContext) async throws {
        let r = c.report
        let file = c.root.appendingPathComponent("Tests/QuickMenuSoundsChecks/Fixtures/baseline.json")
        guard let data = try? Data(contentsOf: file), let frozen = try? JSONDecoder().decode([String: String].self, from: data) else {
            r.fail("baseline not frozen (Fixtures/baseline.json missing)"); return
        }
        let now = try await all(root: c.root, scratch: c.scratch)
        for key in frozen.keys.sorted() {
            r.check(now[key] == frozen[key], "\(key) unchanged: was \(frozen[key]!), now \(now[key] ?? "missing")")
        }
        r.check(Set(now.keys).subtracting(frozen.keys).isEmpty, "no unexpected baseline entries: \(Set(now.keys).subtracting(frozen.keys).sorted())")
        let candidate = c.root.appendingPathComponent(candidateFixture)
        if FileManager.default.fileExists(atPath: candidate.path) {
            let copy = c.scratch.appendingPathComponent("candidate-names/library.json")
            try FileManager.default.createDirectory(at: copy.deletingLastPathComponent(), withIntermediateDirectories: true)
            try? FileManager.default.removeItem(at: copy)
            try FileManager.default.copyItem(at: candidate, to: copy)
            let before = try Data(contentsOf: copy)
            let reopened = try await QMSSession.reopen(copy)
            let names = try await reopened.session.snapshot().definitions.map(\.name)
            _ = try await reopened.session.checkpoint()
            // Fresh libraries only: an existing library is never extended with new built-ins or rewritten.
            r.check(names == ["Everyday", "Filters"], "a saved Quick Menu library opens with only its own sounds, got \(names)")
            r.check(try Data(contentsOf: copy) == before, "opening and saving an unchanged existing library never rewrites it")
        } else { r.fail("candidate library fixture missing") }
    }
}
